class Solution:
    def checkPalindromeFormation(self, s: str) -> bool:
        i, j, m = 0, len(s) - 1, 0
        while i < j:
            if s[i] != s[j]:
                m += 1
            i += 1
            j -= 1
        return m <= 2

c.cpp:
class Solution {
public:
    bool checkPalindromeFormation(string s) {
        int i = 0, j = s.size() - 1, m = 0;
        while (i < j) {
            if (s[i] != s[j]) m++;
            i++; j--;
        }
        return m <= 2;
    }
};

c.java:
class Solution {
    public boolean checkPalindromeFormation(String s) {
        int i = 0, j = s.length() - 1, m = 0;
        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) m++;
            i++; j--;
        }
        return m <= 2;
    }
}

